import Foundation

/// S1 — the arithmetic the Spool prototype runs on, reproduced bit for bit.
///
/// The golden fixtures (`Fixtures/spool/spool_golden.json`) are SHA-256 hashes of the prototype's SVG,
/// generated by node (`Scripts/spool_golden.mjs`). Some numbers in that SVG are printed with full
/// precision (for example the listening mouth's `rx = 9 + sin(3t)·1.5`), so the port must produce the
/// *same doubles* as V8, not merely close ones:
///
/// - `sin`, `cos`, `exp` are V8's fdlibm ports (`src/base/ieee754.cc`) with the `a·b ± c` contractions
///   the node build compiles to fused multiply-adds. Measured against node 26 on 200 000 arguments:
///   0 differences (Darwin's libm differs on ~4 % of them).
/// - `hypot` is V8's builtin (normalise by the largest, Kahan-sum the squares, `sqrt · max`).
/// - `pow` is Darwin's, which agreed with node on every tested argument in the ranges Spool uses.
/// - `max`/`min` follow `Math.max`/`Math.min` on signed zeros; `round` is `Math.round`.
/// - `fixed2` is `Number(x.toFixed(2))`, the prototype's `f()`.
///
/// Every function here is pure. The product uses the same maths as the parity tests, so there is one
/// code path for the pill and the golden frames.
enum SpoolMath {
    static let tau = Double.pi * 2

    // MARK: - Prototype helpers (`clamp`, `mix`, `sm`, `f`)

    /// `Math.max(a, Math.min(b, x))`.
    static func clamp(_ x: Double, _ a: Double = 0, _ b: Double = 1) -> Double {
        max(a, min(b, x))
    }

    /// `a + (b - a) * p`.
    static func mix(_ a: Double, _ b: Double, _ p: Double) -> Double {
        a + (b - a) * p
    }

    /// Smoothstep on `clamp(x, 0, 1)`: `x·x·(3 − 2x)`.
    static func sm(_ x: Double) -> Double {
        let c = clamp(x)
        return c * c * (3 - 2 * c)
    }

    /// `Math.max` for two numbers: NaN wins, and `+0` is larger than `−0`.
    static func max(_ a: Double, _ b: Double) -> Double {
        if a.isNaN || b.isNaN { return .nan }
        if a == b { return a.sign == .plus ? a : b }
        return a > b ? a : b
    }

    /// `Math.min` for two numbers: NaN wins, and `−0` is smaller than `+0`.
    static func min(_ a: Double, _ b: Double) -> Double {
        if a.isNaN || b.isNaN { return .nan }
        if a == b { return a.sign == .minus ? a : b }
        return a < b ? a : b
    }

    /// `Math.round`: nearest integer, halves toward +∞.
    static func round(_ x: Double) -> Double {
        guard x.isFinite else { return x }
        let down = x.rounded(.down)
        return x - down >= 0.5 ? down + 1 : down
    }

    /// `Number(x.toFixed(2))` — the prototype's `f()`.
    ///
    /// `toFixed` picks the integer `n` closest to `x·100` computed on the *exact* binary value of `x`,
    /// taking the larger magnitude on an exact tie; a naive `(x * 100).rounded()` disagrees whenever
    /// the product rounds across a half (e.g. `8.345`). The product's rounding error is recovered
    /// exactly with a fused multiply-add, so the comparison with the half is exact.
    static func fixed2(_ x: Double) -> Double {
        guard x.isFinite, abs(x) < 1e21 else { return x }
        let y = abs(x)
        let product = y * 100
        let error = (-product).addingProduct(y, 100)      // y·100 − product, exactly
        let floor = product.rounded(.down)
        let fraction = product - floor                     // exact: same binade as product
        let distance = (fraction - 0.5) + error            // sign is exact
        let n = distance >= 0 ? floor + 1 : floor
        let value = n / 100
        return x.sign == .minus ? -value : value
    }

    // MARK: - V8 transcendental functions

    static func sin(_ x: Double) -> Double {
        let ix = high(x) & 0x7fff_ffff
        if ix <= 0x3fe9_21fb { return kernelSin(x, 0, 0) }
        if ix >= 0x7ff0_0000 { return x - x }
        guard let (n, y0, y1) = remPio2(x) else { return Foundation.sin(x) }
        switch n & 3 {
        case 0: return kernelSin(y0, y1, 1)
        case 1: return kernelCos(y0, y1)
        case 2: return -kernelSin(y0, y1, 1)
        default: return -kernelCos(y0, y1)
        }
    }

    static func cos(_ x: Double) -> Double {
        let ix = high(x) & 0x7fff_ffff
        if ix <= 0x3fe9_21fb { return kernelCos(x, 0) }
        if ix >= 0x7ff0_0000 { return x - x }
        guard let (n, y0, y1) = remPio2(x) else { return Foundation.cos(x) }
        switch n & 3 {
        case 0: return kernelCos(y0, y1)
        case 1: return -kernelSin(y0, y1, 1)
        case 2: return -kernelCos(y0, y1)
        default: return kernelSin(y0, y1, 1)
        }
    }

    static func exp(_ input: Double) -> Double {
        var x = input
        let oThreshold = 7.09782712893383973096e+02, uThreshold = -7.45133219101941108420e+02
        let ln2HI = [6.93147180369123816490e-01, -6.93147180369123816490e-01]
        let ln2LO = [1.90821492927058770002e-10, -1.90821492927058770002e-10]
        let invln2 = 1.44269504088896338700e+00
        let p1 = 1.66666666666666019037e-01, p2 = -2.77777777770155933842e-03, p3 = 6.61375632143793436117e-05,
            p4 = -1.65339022054652515390e-06, p5 = 4.13813679705723846039e-08
        let halF = [0.5, -0.5]
        var hx = UInt32(bitPattern: high(x))
        let xsb = Int((hx >> 31) & 1)
        hx &= 0x7fff_ffff
        if hx >= 0x4086_2E42 {
            if hx >= 0x7ff0_0000 {
                if ((hx & 0xfffff) | low(x)) != 0 { return x + x }
                return xsb == 0 ? x : 0
            }
            if x > oThreshold { return .infinity }
            if x < uThreshold { return 0 }
        }
        var hi = 0.0, lo = 0.0, k = 0
        if hx > 0x3FD6_2E42 {
            if hx < 0x3FF0_A2B2 {
                if x == 1 { return M_E }
                hi = x - ln2HI[xsb]
                lo = ln2LO[xsb]
                k = 1 - xsb - xsb
            } else {
                k = Int(Int32(halF[xsb].addingProduct(invln2, x)))
                let t = Double(k)
                hi = x.addingProduct(-t, ln2HI[0])
                lo = t * ln2LO[0]
            }
            x = hi - lo
        } else if hx < 0x3e30_0000 {
            if 1.0e300 + x > 1 { return 1 + x }
        }
        let t = x * x
        let poly = p1.addingProduct(t, p2.addingProduct(t, p3.addingProduct(t, p4.addingProduct(t, p5))))
        let c = x.addingProduct(-t, poly)
        if k == 0 { return 1 - ((x * c) / (c - 2.0) - x) }
        let y = 1 - ((lo - (x * c) / (2.0 - c)) - hi)
        if k >= -1021 {
            if k == 1024 { return y * 2.0 * 8.98846567431157953865e+307 }
            return y * Double(bitPattern: UInt64(UInt32(bitPattern: Int32(0x3ff0_0000 + (k << 20)))) << 32)
        }
        let twopk = Double(bitPattern: UInt64(UInt32(bitPattern: Int32(0x3ff0_0000 + ((k + 1000) << 20)))) << 32)
        return y * twopk * 9.33263618503218878990e-302
    }

    /// `Math.hypot(a, b)` as V8's builtin computes it.
    static func hypot(_ a: Double, _ b: Double) -> Double {
        if a.isInfinite || b.isInfinite { return .infinity }
        if a.isNaN || b.isNaN { return .nan }
        let first = abs(a), second = abs(b)
        let largest = Swift.max(first, second)
        if largest == 0 { return 0 }
        var sum = 0.0, compensation = 0.0
        for value in [first, second] {
            let n = value / largest
            let summand = n * n - compensation
            let preliminary = sum + summand
            compensation = (preliminary - sum) - summand
            sum = preliminary
        }
        return sum.squareRoot() * largest
    }

    static func pow(_ x: Double, _ y: Double) -> Double { Foundation.pow(x, y) }

    // MARK: - fdlibm kernels (as compiled into node: `a·b ± c` in one expression is fused)

    private static func high(_ x: Double) -> Int32 { Int32(bitPattern: UInt32(truncatingIfNeeded: x.bitPattern >> 32)) }
    private static func low(_ x: Double) -> UInt32 { UInt32(truncatingIfNeeded: x.bitPattern) }

    private static func kernelSin(_ x: Double, _ y: Double, _ iy: Int) -> Double {
        let s1 = -1.66666666666666324348e-01, s2 = 8.33333333332248946124e-03, s3 = -1.98412698298579493134e-04,
            s4 = 2.75573137070700676789e-06, s5 = -2.50507602534068634195e-08, s6 = 1.58969099521155010221e-10
        let ix = high(x) & 0x7fff_ffff
        if ix < 0x3e40_0000, Int(x) == 0 { return x }
        let z = x * x
        let v = z * x
        let r = s2.addingProduct(z, s3.addingProduct(z, s4.addingProduct(z, s5.addingProduct(z, s6))))
        if iy == 0 { return x.addingProduct(v, s1.addingProduct(z, r)) }
        let a = (-(v * r)).addingProduct(0.5, y)
        let b = (-y).addingProduct(z, a)
        let c = b.addingProduct(-v, s1)
        return x - c
    }

    private static func kernelCos(_ x: Double, _ y: Double) -> Double {
        let c1 = 4.16666666666666019037e-02, c2 = -1.38888888888741095749e-03, c3 = 2.48015872894767294178e-05,
            c4 = -2.75573143513906633035e-07, c5 = 2.08757232129817482790e-09, c6 = -1.13596475577881948265e-11
        let ix = high(x) & 0x7fff_ffff
        if ix < 0x3e40_0000, Int(x) == 0 { return 1 }
        let z = x * x
        let r = z * c1.addingProduct(z, c2.addingProduct(z, c3.addingProduct(z, c4.addingProduct(z, c5.addingProduct(z, c6)))))
        let d = (-(x * y)).addingProduct(z, r)
        if ix < 0x3FD3_3333 { return 1 - (-d).addingProduct(0.5, z) }
        let qx = ix > 0x3fe9_0000
            ? 0.28125
            : Double(bitPattern: UInt64(UInt32(bitPattern: ix - 0x0020_0000)) << 32)
        let hz = (-qx).addingProduct(0.5, z)
        let a = 1 - qx
        return a - (hz - d)
    }

    private static let npio2hw: [Int32] = [
        0x3FF9_21FB, 0x4009_21FB, 0x4012_D97C, 0x4019_21FB, 0x401F_6A7A, 0x4022_D97C,
        0x4025_FDBB, 0x4029_21FB, 0x402C_463A, 0x402F_6A7A, 0x4031_475C, 0x4032_D97C,
        0x4034_6B9C, 0x4035_FDBB, 0x4037_8FDB, 0x4039_21FB, 0x403A_B41B, 0x403C_463A,
        0x403D_D85A, 0x403F_6A7A, 0x4040_7E4C, 0x4041_475C, 0x4042_106C, 0x4042_D97C,
        0x4043_A28C, 0x4044_6B9C, 0x4045_34AC, 0x4045_FDBB, 0x4046_C6CB, 0x4047_8FDB,
        0x4048_58EB, 0x4049_21FB,
    ]

    /// `__ieee754_rem_pio2` up to the medium range (|x| ≤ 2¹⁹·π/2 ≈ 823 550). Beyond it (hours of
    /// continuous listening) the caller falls back to Darwin's libm: no golden frame goes there.
    private static func remPio2(_ x: Double) -> (Int, Double, Double)? {
        let invpio2 = 6.36619772367581382433e-01
        let pio2_1 = 1.57079632673412561417e+00, pio2_1t = 6.07710050650619224932e-11
        let pio2_2 = 6.07710050630396597660e-11, pio2_2t = 2.02226624879595063154e-21
        let pio2_3 = 2.02226624871116645580e-21, pio2_3t = 8.47842766036889956997e-32
        let hx = high(x)
        let ix = hx & 0x7fff_ffff
        if ix <= 0x3fe9_21fb { return (0, x, 0) }
        if ix < 0x4002_d97c {
            if hx > 0 {
                var z = x - pio2_1
                if ix != 0x3ff9_21fb {
                    let y0 = z - pio2_1t
                    return (1, y0, (z - y0) - pio2_1t)
                }
                z -= pio2_2
                let y0 = z - pio2_2t
                return (1, y0, (z - y0) - pio2_2t)
            }
            var z = x + pio2_1
            if ix != 0x3ff9_21fb {
                let y0 = z + pio2_1t
                return (-1, y0, (z - y0) + pio2_1t)
            }
            z += pio2_2
            let y0 = z + pio2_2t
            return (-1, y0, (z - y0) + pio2_2t)
        }
        guard ix <= 0x4139_21fb else { return nil }
        var t = abs(x)
        let n = Int(Int32(0.5.addingProduct(t, invpio2)))
        let fn = Double(n)
        var r = t.addingProduct(-fn, pio2_1)
        var w = fn * pio2_1t
        var y0 = r - w
        if !(n < 32 && ix != npio2hw[n - 1]) {
            let j = ix >> 20
            var i = j - ((high(y0) >> 20) & 0x7ff)
            if i > 16 {
                t = r
                w = fn * pio2_2
                r = t - w
                w = (-((t - r) - w)).addingProduct(fn, pio2_2t)
                y0 = r - w
                i = j - ((high(y0) >> 20) & 0x7ff)
                if i > 49 {
                    t = r
                    w = fn * pio2_3
                    r = t - w
                    w = (-((t - r) - w)).addingProduct(fn, pio2_3t)
                    y0 = r - w
                }
            }
        }
        let y1 = (r - y0) - w
        return hx < 0 ? (-n, -y0, -y1) : (n, y0, y1)
    }
}
